"""Genera los datos del plantel a partir de las rutas originales y reseñas revisadas.
Ejecutar con Python 3. No modifica los recursos originales.
"""
from pathlib import Path
import json
import re
import unicodedata
import runpy

ROOT = Path(__file__).resolve().parents[1]

def key(value):
    value = re.sub(r'^(?:P?rof\.)\s*', '', value.strip(), flags=re.I)
    return ''.join(c for c in unicodedata.normalize('NFD', value) if unicodedata.category(c) != 'Mn').lower()

