REVIEWS = runpy.run_path(str(ROOT/'tools'/'expanded-reviews.py'))['expand_reviews'](REVIEWS)
AREAS = [('artes-plasticas','Artes Plásticas'),('biologia','Biología'),('c.sociales','Ciencias Sociales'),('computacion','Computación'),('e.fisica','Educación Física'),('filosofia','Filosofía'),('fisica','Física'),('ingles','Inglés'),('lenguaje','Lenguaje'),('matematicas','Matemáticas'),('musica','Música'),('quimica','Química'),('religion','Religión'),('tecnica','Técnica')]
reviews = {key(name):(name,bio) for name,bio in REVIEWS.items()}
people = {}
for folder, label in AREAS:
    directory = ROOT/'profesores'/folder
    for path in sorted(directory.iterdir()):
        if path.suffix.lower() not in ('.jpg','.jpeg','.png','.jfif'):
            continue
        identity = key(path.stem)
        name,bio = reviews.get(identity,(re.sub(r'^Prof\.\s*','',path.stem),''))
        if identity not in people:
            people[identity]={'id':re.sub('[^a-z0-9]+','-',identity),'name':name,'areas':[],'photo':path.relative_to(ROOT).as_posix(),'bio':bio}
        people[identity]['areas'].append(folder)
    for path in directory.glob('*.txt'):
        source=path.read_text(encoding='utf-8-sig')
        for name in re.findall(r'^(?:P?rof\.)\s*(.+)$',source,re.M):
            identity=key(name)
            if identity not in people:
                display,bio=reviews[identity]
                people[identity]={'id':re.sub('[^a-z0-9]+','-',identity),'name':display,'areas':[folder],'photo':None,'bio':bio}
assert len(people)==30, f'Expected 30 unique teachers, found {len(people)}'
payload={'areas':[{'id':a,'name':b} for a,b in AREAS],'teachers':list(people.values())}
(ROOT/'docentes.js').write_text('// Datos del plantel. Rutas originales y reseñas revisadas.\nwindow.schoolStaff = '+json.dumps(payload,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')
print(f'{len(people)} docentes únicos; {sum(not p["photo"] for p in people.values())} sin fotografía; {sum(not p["bio"] for p in people.values())} sin reseña.')
